const data = $input.item.json;

const pilotLeadId = data.pilot_lead_id ? `'${data.pilot_lead_id}'` : 'NULL';
const pilotResponse = (data.pilot_response || '').replace(/'/g, "''");

return {
  json: {
    query: `UPDATE meli_leads SET status = '${data.new_status}', pilot_lead_id = ${pilotLeadId}, sf_response = '${pilotResponse}' WHERE id = '${data.lead_id}'`
  }
};

const body = $input.item.json.body;
const { tel_sufijo, updates } = body;

if (!tel_sufijo || !updates || Object.keys(updates).length === 0) {
  throw new Error('Faltan parámetros');
}

const setClauses = Object.entries(updates)
  .map(([key, value]) => {
    if (typeof value === 'number') return `${key} = ${value}`;
    return `${key} = '${String(value).replace(/'/g, "''")}'`;
  })
  .join(', ');

return {
  json: {
    query: `UPDATE meli_leads SET ${setClauses} WHERE RIGHT(REGEXP_REPLACE(buyer_phone, '[^0-9]', ''), 8) = '${tel_sufijo}' AND status IN ('active', 'sent')`
  }
};

