// confianza 'baja' = versión elegida por default porque el título no la especifica.
const catalog = [
  // CHERY
  { code: 'Arrizo8Long',     id: 315, name: 'ARRIZO 8 HYBRID PHEV Comfort',             match: [/\barrizo ?8\b/] },
