  { code: 'Tiggo7PHEVLong',  id: 494, name: 'TIGGO 7 PRO HYBRID PHEV Premium',          match: [/\btiggo ?7\b/, PHEV] },
  { code: 'Tiggo7FullLong',  id: 311, name: 'TIGGO 7 PRO HYBRID MHEV Premium (c/ADAS)', match: [/\btiggo ?7\b/] },
