  // BAIC
  { code: 'BJ304x4LONG',     id: 319, name: 'BJ30E Hybrid 4x4', match: [/\bbj ?30 ?e?\b/, T4X4] },
  { code: 'BJ304x2LONG',     id: 318, name: 'BJ30E Hybrid 4x2', match: [/\bbj ?30 ?e?\b/, T4X2] },
  { code: 'BJ304x2LONG',     id: 318, name: 'BJ30E Hybrid 4x2', match: [/\bbj ?30 ?e?\b/], confianza: 'baja' },
  { code: 'BJ40ProLONG',     id: 317, name: 'BJ40 Pro',         match: [/\bbj ?40\b/] },
  { code: 'BJ60LONG',        id: 320, name: 'BJ60 MHEV',        match: [/\bbj ?60\b/] },
  { code: 'EU5Long',         id: 321, name: 'EU5 EV',           match: [/\beu ?5\b/] },
  { code: 'U5PlusLONG',      id: 322, name: 'U5 Plus',          match: [/\bu ?5\b/] },
  { code: 'X35LuxuryLONG',   id: 323, name: 'X35 Luxury',       match: [/\bx ?35\b/] },
  { code: 'X55IIHybridLONG', id: 332, name: 'X55 II Hybrid',    match: [/\bx ?55\b/, HYB] },
  { code: 'X55PlusLONG',     id: 324, name: 'X55 Plus',         match: [/\bx ?55\b/, /\bplus\b/] },
  { code: 'X55IILONG',       id: 325, name: 'X55 II Luxury',    match: [/\bx ?55 ?(ii|2)\b/] },
  { code: 'X55IILONG',       id: 325, name: 'X55 II Luxury',    match: [/\bx ?55\b/], confianza: 'baja' },

  // ARCFOX
  { code: 'KaolaLong',       id: 328, name: 'KAOLA EV',         match: [/\bkaola\b/] },
  { code: 'T1Long',          id: 326, name: 'T1 EV',            match: [/\bt ?1\b/, EVCTX] },
  { code: 'T5Long',          id: 327, name: 'T5 EV',            match: [/\bt ?5\b/, EVCTX] },
  { code: 'S5Long',          id: 329, name: 'S5 EV',            match: [/\bs ?5\b/, EVCTX] },
];

const normalize = (s) =>
  (s || '')
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();

