  },
};

const lead = $input.item.json;
const normalizarTel = (tel) => {
  if (!tel) return null;
  const digits = tel.toString().replace(/\D/g, '');
  return digits.slice(-8);
};
const normalizarBuyerPhone = (tel) => {
  if (!tel) return null;
  let digits = tel.toString().replace(/\D/g, '');
  if (digits.startsWith('549')) return '+' + digits;
  if (digits.startsWith('54')) return '+549' + digits.slice(2);
  if (digits.startsWith('9') && digits.length >= 10) return '+54' + digits;
  return '+549' + digits;
};
const sufijo1 = normalizarTel(lead.asesor_phone);
const sufijo2 = normalizarTel(lead.asesor_phone2);
return {
  json: {
    ...lead,
    buyer_phone: normalizarBuyerPhone(lead.buyer_phone),
    asesor_sufijo1: sufijo1 || '',
    asesor_sufijo2: sufijo2 || ''
  }
};

const lead = $('Normalizar teléfonos').item.json;

const marcaConfig = {
  'BAIC': { origin: 'BAICLONG_MELI1', business_type_id: 11 },
  'CHERY': { origin: 'CHLONG_MELI_1', business_type_id: 14 },
  'ARCFOX': { origin: 'ARCLONG_MELI1', business_type_id: 18 },
};

// Prioridad de búsqueda de asesor según marca de la publicación
const prioridadPorMarca = {
  'CHERY': ['CHERY', 'BAIC'],
  'BAIC': ['BAIC', 'CHERY'],
  'ARCFOX': ['BAIC', 'CHERY'], // ajustá si Arcfox tiene su propio grupo
};

const dominioPorMarca = { 'CHERY': 'cherylong', 'BAIC': 'baiclong' };

const getLast8 = (phone) => (phone || '').toString().replace(/\D/g, '').slice(-8);

// Normaliza a 549 + 10 dígitos (celular AR), sin "+"
const normalizePhone = (phone) => {
  const d = (phone || '').toString().replace(/\D/g, '');
  return d.length >= 10 ? '549' + d.slice(-10) : null;
};

const getUsers = (nodeName) => {
  try {
    return $(nodeName).all().flatMap(i => i.json?.data?.users || []);
  } catch (e) {
    console.warn(`No pude leer ${nodeName}: ${e.message}`);
    return [];
  }
};

// sufijo (últimos 8 dígitos) -> asesor. Si hay colisión, gana el que tenga el dominio de la marca.
const buildMap = (users, dominio) => {
  const map = {};
  for (const u of users) {
    if (u.status !== 'active' || !u.email) continue;
    const key = getLast8(u.phone);
    if (key.length < 8) continue; // descarta teléfonos basura (ej: un email en el campo phone)
    const pref = !!dominio && u.email.toLowerCase().includes(dominio);
    if (!map[key] || (pref && !map[key]._pref)) {
      map[key] = {
        name: `${u.first_name || ''} ${u.last_name || ''}`.trim(),
        pilot_user: u.email.trim().toLowerCase(),
        phone: normalizePhone(u.phone),
        _pref: pref,
      };
    }
  }
  return map;
};

const maps = {
  CHERY: buildMap(getUsers('obtenerAsesoresChery'), dominioPorMarca.CHERY),
  BAIC: buildMap(getUsers('obtenerAsesoresBaic'), dominioPorMarca.BAIC),
};

// Marca se detecta del título de la publicación
const determineMarca = (lead) => {
  const texto = (lead.item_titulo || '').toLowerCase();
  if (texto.includes('chery')) return 'CHERY';
  if (texto.includes('arcfox')) return 'ARCFOX';
  if (texto.includes('baic')) return 'BAIC';
  return null;
};

const marca = determineMarca(lead);
const config = marca ? marcaConfig[marca] : null;
if (!marca) {
  console.warn(`No se pudo determinar la marca. Título: ${lead.item_titulo}, Link: ${lead.item_permalink}`);
}

const sufijo = getLast8(lead.asesor_phone);
const orden = prioridadPorMarca[marca] || ['BAIC', 'CHERY'];

let asesorMatch = null;
let asesorFuente = null;
for (const b of orden) {
  if (maps[b][sufijo]) {
    asesorMatch = maps[b][sufijo];
    asesorFuente = b;
    break;
  }
}

if (!asesorMatch) {
  console.warn(`Asesor no encontrado: ${lead.asesor_phone} (sufijo: ${sufijo})`);
}

return {
  json: {
    ...lead,
    pilot_assigned_user: asesorMatch?.pilot_user || null,
    asesor_nombre_match: asesorMatch?.name || null,
    asesor_telefono_normalizado: asesorMatch?.phone || normalizePhone(lead.asesor_phone),
    asesor_fuente: asesorFuente,
    marca_detectada: marca,
    pilot_origin: config?.origin || null,
    pilot_business_type_id: config?.business_type_id || null,
  },
};

const pilotResponse = $input.item.json;
const prev = $('PayloadPilot').item.json;

const pilotLeadId = pilotResponse?.data?.welcome_id || null;
const success = pilotResponse.success && !pilotResponse.error && !pilotResponse.message?.toLowerCase().includes('error');

return {
  json: {
    lead_id: prev.lead_id,
    pilot_lead_id: pilotLeadId,
    new_status: success ? 'sent' : 'error',
    pilot_response: JSON.stringify(pilotResponse)
  }
};

